// Register a global interrupt callback. We cannot safely construct function pointers here,
// so exercise the API path that clears the callback by passing NULL.
// Allowed per API: cb may be NULL to clear existing callback.
GEOSInterruptCallback *prev = GEOS_interruptRegisterCallback(nullptr);
(void)prev; // ignore prior callback pointer

// Register a per-context interrupt callback; pass NULL to clear (allowed by API).
// The fuzzer provides a wrapper object 'handle' of type GEOSContextHandle_t * (a holder for the real handle).
// We must pass the dereferenced value to the GEOS API.
GEOSContextInterruptCallback *prev = GEOSContext_setInterruptCallback_r(*handle, nullptr, (void*)handle);
(void)prev; // ignore previous callback
// Validation: uses a valid context by dereferencing the wrapper; userData is a stable pointer (the wrapper).

// Initialize a new re-entrant GEOS context and wrap it in a holder object that the fuzzer pool manages.
GEOSContextHandle_t real = GEOS_init_r();
if (!real) { FUZZ_BAIL(); }
// Allocate a wrapper to store the handle so downstream stubs can dereference it when calling GEOS APIs.
GEOSContextHandle_t *handle = new GEOSContextHandle_t; *handle = real;
// Track per-context owned sequence count for safe GEOS_finish_r
FUZZ_SET_ATTR_INT(handle, "seq_count", 0);
// Validation: successfully created context and stored in a durable wrapper for later dereference.

// Ensure no outstanding coordinate sequences (or other tracked objects) are owned by this context.
int seq_count = FUZZ_GET_ATTR_INT(handle, "seq_count");
if (seq_count != 0) { FUZZ_BAIL(); }
// Finish and free the context. Do not use the handle afterward.
GEOS_finish_r(*handle);
// Free the wrapper allocated in GEOS_init_r
delete handle;
// Validation: enforces no leaked sequences via attribute and correctly dereferences wrapper to free the context.

// Set notice handler; pass NULL to clear (allowed by API). Cannot define variadic callback here.
GEOSMessageHandler prev = GEOSContext_setNoticeHandler_r(*handle, nullptr);
(void)prev;
// Validation: passes a valid context by dereferencing the wrapper; leaves handler cleared.

// Set error handler; pass NULL to clear (allowed by API). Cannot define variadic callback here.
GEOSMessageHandler prev = GEOSContext_setErrorHandler_r(*handle, nullptr);
(void)prev;
// Validation: passes a valid context by dereferencing the wrapper; leaves handler cleared.

// Set (message, userdata) notice handler. Pass NULL handler to clear; supply stable userData (the wrapper pointer).
GEOSMessageHandler_r prev = GEOSContext_setNoticeMessageHandler_r(*handle, nullptr, (void*)handle);
(void)prev;
// Validation: uses dereferenced context and stable userData pointer that remains valid while handler is active.

// Set (message, userdata) error handler. Pass NULL handler to clear; supply stable userData (the wrapper pointer).
GEOSMessageHandler_r prev = GEOSContext_setErrorMessageHandler_r(*handle, nullptr, (void*)handle);
(void)prev;
// Validation: uses dereferenced context and stable userData pointer that remains valid while handler is active.

// Create a coordinate sequence with dims in [2,4] and a bounded size.
unsigned int dims = (unsigned int)(2 + (*FUZZ_PARAM(unsigned int) % 3)); // 2..4
unsigned int size = (unsigned int)(*FUZZ_PARAM(unsigned int) % 65); // 0..64
GEOSCoordSequence *seq = GEOSCoordSeq_create_r(*handle, size, dims);
if (!seq) { FUZZ_BAIL(); }
// Track dimensions and size for later validation/IO operations
FUZZ_SET_ATTR_INT(seq, "dims", (int)dims);
FUZZ_SET_ATTR_INT(seq, "hasZ", dims >= 3 ? 1 : 0);
FUZZ_SET_ATTR_INT(seq, "hasM", dims == 4 ? 1 : 0);
FUZZ_SET_ATTR_INT(seq, "seq_size", (int)size);
FUZZ_SET_ATTR_PTR(seq, "ctx", (void*)handle);
// Bump context refcount of sequences
FUZZ_SET_ATTR_INT(handle, "seq_count", FUZZ_GET_ATTR_INT(handle, "seq_count") + 1);
// Validation: ensures valid dims range, records attributes, and increments context-owned sequence count.

// Create a sequence specifying hasZ/hasM flags (0/1)
unsigned int size = (unsigned int)(*FUZZ_PARAM(unsigned int) % 65); // 0..64
int hasZ = (int)(*FUZZ_PARAM(unsigned int) & 1);
int hasM = (int)((*FUZZ_PARAM(unsigned int) >> 1) & 1);
GEOSCoordSequence *seq = GEOSCoordSeq_createWithDimensions_r(*handle, size, hasZ, hasM);
if (!seq) { FUZZ_BAIL(); }
int dims = 2 + (hasZ ? 1 : 0) + (hasM ? 1 : 0);
FUZZ_SET_ATTR_INT(seq, "dims", dims);
FUZZ_SET_ATTR_INT(seq, "hasZ", hasZ);
FUZZ_SET_ATTR_INT(seq, "hasM", hasM);
FUZZ_SET_ATTR_INT(seq, "seq_size", (int)size);
FUZZ_SET_ATTR_PTR(seq, "ctx", (void*)handle);
FUZZ_SET_ATTR_INT(handle, "seq_count", FUZZ_GET_ATTR_INT(handle, "seq_count") + 1);
// Validation: conforms to Z/M semantics and ties sequence to its creating context.

// Prepare an interleaved source buffer. Capacity for up to 64 coords with up to 4 dims.
const double *raw = *FUZZ_PARAM(double[256]); // 64 * 4
int hasZ = (int)(*FUZZ_PARAM(unsigned int) & 1);
int hasM = (int)((*FUZZ_PARAM(unsigned int) >> 1) & 1);
unsigned int dims = 2 + (hasZ ? 1 : 0) + (hasM ? 1 : 0);
unsigned int maxCoords = 256u / (unsigned int)dims;
