GEOSCoordSequence *seq = GEOSCoordSeq_copyFromBuffer_r(*handle, raw, size, hasZ, hasM);
if (!seq) { FUZZ_BAIL(); }
FUZZ_SET_ATTR_INT(seq, "dims", (int)dims);
FUZZ_SET_ATTR_INT(seq, "hasZ", hasZ);
FUZZ_SET_ATTR_INT(seq, "hasM", hasM);
FUZZ_SET_ATTR_INT(seq, "seq_size", (int)size);
FUZZ_SET_ATTR_PTR(seq, "ctx", (void*)handle);
FUZZ_SET_ATTR_INT(handle, "seq_count", FUZZ_GET_ATTR_INT(handle, "seq_count") + 1);
// Validation: ensures buffer capacity based on dims and size; associates sequence with context.

// Prepare separate component arrays. Ensure x, y non-NULL and sized; z/m optional.
const double *x = *FUZZ_PARAM(double[64]);
const double *y = *FUZZ_PARAM(double[64]);
// Randomly decide presence of z/m arrays
int z_present = (int)(*FUZZ_PARAM(unsigned int) & 1);
int m_present = (int)((*FUZZ_PARAM(unsigned int) >> 1) & 1);
const double *z = z_present ? *FUZZ_PARAM(double[64]) : nullptr;
const double *m = m_present ? *FUZZ_PARAM(double[64]) : nullptr;
unsigned int size = (unsigned int)(*FUZZ_PARAM(unsigned int) % 65); // 0..64
GEOSCoordSequence *seq = GEOSCoordSeq_copyFromArrays_r(*handle, x, y, z, m, size);
if (!seq) { FUZZ_BAIL(); }
int hasZ = z_present ? 1 : 0;
int hasM = m_present ? 1 : 0;
int dims = 2 + hasZ + hasM;
FUZZ_SET_ATTR_INT(seq, "dims", dims);
FUZZ_SET_ATTR_INT(seq, "hasZ", hasZ);
FUZZ_SET_ATTR_INT(seq, "hasM", hasM);
FUZZ_SET_ATTR_INT(seq, "seq_size", (int)size);
FUZZ_SET_ATTR_PTR(seq, "ctx", (void*)handle);
FUZZ_SET_ATTR_INT(handle, "seq_count", FUZZ_GET_ATTR_INT(handle, "seq_count") + 1);
// Validation: guarantees x/y arrays present and sized; tracks Z/M presence and size attributes.

// Copy sequence to an interleaved buffer. Enforce buffer capacity.
int size = FUZZ_GET_ATTR_INT(seq, "seq_size");
int hasZ = FUZZ_GET_ATTR_INT(seq, "hasZ");
int hasM = FUZZ_GET_ATTR_INT(seq, "hasM");
if (size < 0) { FUZZ_BAIL(); }
unsigned int dims = 2u + (unsigned int)(hasZ ? 1 : 0) + (unsigned int)(hasM ? 1 : 0);
unsigned int needed = (unsigned int)size * dims;
if (needed > 256u) { FUZZ_BAIL(); }
// Provide sufficient output storage
double outbuf[256];
int ok = GEOSCoordSeq_copyToBuffer_r(*handle, seq, outbuf, hasZ, hasM);
if (!ok) { FUZZ_BAIL(); }
// Validation: ensures destination capacity >= needed and calls API with dereferenced context.

// Copy sequence to separate arrays; x and y must be non-NULL; z/m may be NULL.
int size = FUZZ_GET_ATTR_INT(seq, "seq_size");
if (size < 0 || size > 128) { FUZZ_BAIL(); }
// Prepare destination arrays
double x[128];
double y[128];
double z[128];
double m[128];
// Randomize whether to request Z/M output arrays
int wantZ = (int)(*FUZZ_PARAM(unsigned int) & 1);
int wantM = (int)((*FUZZ_PARAM(unsigned int) >> 1) & 1);
double *zp = wantZ ? z : nullptr;
double *mp = wantM ? m : nullptr;
int ok = GEOSCoordSeq_copyToArrays_r(*handle, seq, x, y, zp, mp);
if (!ok) { FUZZ_BAIL(); }
// Validation: ensures destination arrays are large enough and optional Z/M pointers follow API rules.

// Clone the input coordinate sequence into this context.
GEOSCoordSequence *seq_clone = GEOSCoordSeq_clone_r(*handle, seq);
if (!seq_clone) { FUZZ_BAIL(); }
// Mirror attributes from original sequence
int dims = FUZZ_GET_ATTR_INT(seq, "dims");
int hasZ = FUZZ_GET_ATTR_INT(seq, "hasZ");
int hasM = FUZZ_GET_ATTR_INT(seq, "hasM");
int sz = FUZZ_GET_ATTR_INT(seq, "seq_size");
FUZZ_SET_ATTR_INT(seq_clone, "dims", dims);
FUZZ_SET_ATTR_INT(seq_clone, "hasZ", hasZ);
FUZZ_SET_ATTR_INT(seq_clone, "hasM", hasM);
FUZZ_SET_ATTR_INT(seq_clone, "seq_size", sz);
FUZZ_SET_ATTR_PTR(seq_clone, "ctx", (void*)handle);
FUZZ_SET_ATTR_INT(handle, "seq_count", FUZZ_GET_ATTR_INT(handle, "seq_count") + 1);
// Validation: cloned sequence inherits attributes and is tracked under the same context.

// Destroy a coordinate sequence; ensure it belongs to this context if tracked.
void *owner = FUZZ_GET_ATTR_PTR(seq, "ctx");
if (owner && owner != (void*)handle) { FUZZ_BAIL(); }
GEOSCoordSeq_destroy_r(*handle, seq);
// Decrement context sequence count if we tracked it
int seq_count = FUZZ_GET_ATTR_INT(handle, "seq_count");
if (seq_count > 0) { FUZZ_SET_ATTR_INT(handle, "seq_count", seq_count - 1); }
// Validation: checks context ownership attribute and decrements refcount to allow GEOS_finish_r later.

// Query whether the sequence stores Z ordinates. Compare against tracked metadata if available.
char hz = GEOSCoordSeq_hasZ_r(*handle, seq);
if (hz == 2) { FUZZ_BAIL(); } // exception case
int tracked_hasZ = FUZZ_GET_ATTR_INT(seq, "hasZ");
if (tracked_hasZ == 0 || tracked_hasZ == 1) {
    FUZZ_ASSERT((int)hz == tracked_hasZ, "hasZ result must match sequence metadata");
}
// Validation: ensures dereferenced context use and asserts property against stored attributes when present.

// Query whether the sequence stores M ordinates. Compare against tracked metadata if available.
char hm = GEOSCoordSeq_hasM_r(*handle, seq);
if (hm == 2) { FUZZ_BAIL(); } // exception case
int tracked_hasM = FUZZ_GET_ATTR_INT(seq, "hasM");
if (tracked_hasM == 0 || tracked_hasM == 1) {
    FUZZ_ASSERT((int)hm == tracked_hasM, "hasM result must match sequence metadata");
}
// Validation: uses dereferenced context and validates property consistency with stored attributes.

// Set X ordinate at a valid index within the sequence size.
int size = FUZZ_GET_ATTR_INT(seq, "seq_size");
if (size <= 0) { FUZZ_BAIL(); }
unsigned int idx = (unsigned int)(*FUZZ_PARAM(unsigned int) % (unsigned int)size);
double val = *FUZZ_PARAM(double);
