double val = *FUZZ_PARAM(double);
int ok = GEOSCoordSeq_setY_r(*handle, seq, idx, val);
if (!ok) { FUZZ_BAIL(); }
// Validation: enforces idx within range and uses dereferenced context; checks return for exceptions.

