unsigned int idx = (unsigned int)(*FUZZ_PARAM(unsigned int) % (unsigned int)size);
double val = *FUZZ_PARAM(double);
int ok = GEOSCoordSeq_setZ_r(*handle, seq, idx, val);
if (!ok) { FUZZ_BAIL(); }
// Validation: index within [0,size) and Z dimension required.

