double val = *FUZZ_PARAM(double);
int ok = GEOSCoordSeq_setM_r(*handle, seq, idx, val);
if (!ok) { FUZZ_BAIL(); }
// Validation: index within [0,size) and M dimension required.

// Set both X and Y at a valid index.
int size = FUZZ_GET_ATTR_INT(seq, "seq_size");
if (size <= 0) { FUZZ_BAIL(); }
unsigned int idx = (unsigned int)(*FUZZ_PARAM(unsigned int) % (unsigned int)size);
double x = *FUZZ_PARAM(double);
double y = *FUZZ_PARAM(double);
int ok = GEOSCoordSeq_setXY_r(*handle, seq, idx, x, y);
if (!ok) { FUZZ_BAIL(); }
// Validation: ensures idx in-range and uses dereferenced context.

// Set X,Y,Z: requires sequence to have Z and idx in range.
int size = FUZZ_GET_ATTR_INT(seq, "seq_size");
int hasZ = FUZZ_GET_ATTR_INT(seq, "hasZ");
if (size <= 0 || hasZ != 1) { FUZZ_BAIL(); }
unsigned int idx = (unsigned int)(*FUZZ_PARAM(unsigned int) % (unsigned int)size);
double x = *FUZZ_PARAM(double);
double y = *FUZZ_PARAM(double);
double z = *FUZZ_PARAM(double);
int ok = GEOSCoordSeq_setXYZ_r(*handle, seq, idx, x, y, z);
