// Validation: enforces Z presence and index bounds.

// Set an arbitrary ordinate by dimension index; dim must be < dims and idx < size.
int size = FUZZ_GET_ATTR_INT(seq, "seq_size");
int dims = FUZZ_GET_ATTR_INT(seq, "dims");
if (size <= 0 || dims < 2 || dims > 4) { FUZZ_BAIL(); }
