if (size <= 0) { FUZZ_BAIL(); }
unsigned int idx = (unsigned int)(*FUZZ_PARAM(unsigned int) % (unsigned int)size);
double out = 0.0;
int ok = GEOSCoordSeq_getY_r(*handle, seq, idx, &out);
if (!ok) { FUZZ_BAIL(); }
// Validation: non-NULL val and in-range index.

