int size = FUZZ_GET_ATTR_INT(seq, "seq_size");
int hasM = FUZZ_GET_ATTR_INT(seq, "hasM");
if (size <= 0 || hasM != 1) { FUZZ_BAIL(); }
unsigned int idx = (unsigned int)(*FUZZ_PARAM(unsigned int) % (unsigned int)size);
double out = 0.0;
int ok = GEOSCoordSeq_getM_r(*handle, seq, idx, &out);
if (!ok) { FUZZ_BAIL(); }
// Validation: enforces M presence and idx bounds.

// Read X and Y at a valid index; x and y must be non-NULL.
int size = FUZZ_GET_ATTR_INT(seq, "seq_size");
if (size <= 0) { FUZZ_BAIL(); }
unsigned int idx = (unsigned int)(*FUZZ_PARAM(unsigned int) % (unsigned int)size);
double x = 0.0, y = 0.0;
int ok = GEOSCoordSeq_getXY_r(*handle, seq, idx, &x, &y);
if (!ok) { FUZZ_BAIL(); }
// Validation: non-NULL outputs and valid index.

// Read X,Y,Z at a valid index; sequence must have Z.
int size = FUZZ_GET_ATTR_INT(seq, "seq_size");
int hasZ = FUZZ_GET_ATTR_INT(seq, "hasZ");
if (size <= 0 || hasZ != 1) { FUZZ_BAIL(); }
unsigned int idx = (unsigned int)(*FUZZ_PARAM(unsigned int) % (unsigned int)size);
double x = 0.0, y = 0.0, z = 0.0;
int ok = GEOSCoordSeq_getXYZ_r(*handle, seq, idx, &x, &y, &z);
if (!ok) { FUZZ_BAIL(); }
// Validation: ensures Z presence and non-NULL outputs.

// Read the dim-th ordinate at a valid index; dim must be within [0,dims).
int size = FUZZ_GET_ATTR_INT(seq, "seq_size");
int dims = FUZZ_GET_ATTR_INT(seq, "dims");
if (size <= 0 || dims < 2 || dims > 4) { FUZZ_BAIL(); }
unsigned int idx = (unsigned int)(*FUZZ_PARAM(unsigned int) % (unsigned int)size);
unsigned int dim = (unsigned int)(*FUZZ_PARAM(unsigned int) % (unsigned int)dims);
double out = 0.0;
int ok = GEOSCoordSeq_getOrdinate_r(*handle, seq, idx, dim, &out);
if (!ok) { FUZZ_BAIL(); }
// Validation: passes non-NULL output and enforces dimension range.

// Retrieve sequence size; compare against tracked metadata if available.
unsigned int sz = 0;
int ok = GEOSCoordSeq_getSize_r(*handle, seq, &sz);
if (!ok) { FUZZ_BAIL(); }
int tracked = FUZZ_GET_ATTR_INT(seq, "seq_size");
if (tracked >= 0) { FUZZ_ASSERT((int)sz == tracked, "Reported size must match tracked size"); }
// Validation: non-NULL pointer and property assertion when metadata is present.

// Retrieve sequence dimensionality; assert against tracked dims when available.
