int ok = GEOSCoordSeq_getDimensions_r(*handle, seq, &dims_out);
if (!ok) { FUZZ_BAIL(); }
int tracked_dims = FUZZ_GET_ATTR_INT(seq, "dims");
if (tracked_dims >= 2 && tracked_dims <= 4) {
    FUZZ_ASSERT((int)dims_out == tracked_dims, "Dimensions must match tracked metadata");
}
// Validation: ensures non-NULL pointer and property consistency.

// Determine if sequence is CCW; API returns 1 on success, 0 on exception.
char is_ccw = 0;
int ok = GEOSCoordSeq_isCCW_r(*handle, seq, &is_ccw);
if (!ok) { FUZZ_BAIL(); }
// Validation: passes a non-NULL output flag; no assumption that seq is a closed ring.

// Build a simple LineString (2 points) and a Point, then project.
// Create a 2D coord sequence with 2 points for the line.
GEOSCoordSequence *ls_seq = GEOSCoordSeq_createWithDimensions_r(*handle, 2u, 0, 0);
if (!ls_seq) { FUZZ_BAIL(); }
// Populate coordinates
GEOSCoordSeq_setXY_r(*handle, ls_seq, 0u, *FUZZ_PARAM(double), *FUZZ_PARAM(double));
GEOSCoordSeq_setXY_r(*handle, ls_seq, 1u, *FUZZ_PARAM(double), *FUZZ_PARAM(double));
GEOSGeometry *line = GEOSGeom_createLineString_r(*handle, ls_seq); // ownership of ls_seq transfers
if (!line) { FUZZ_BAIL(); }
// Create a Point from XY
double px = *FUZZ_PARAM(double);
double py = *FUZZ_PARAM(double);
GEOSGeometry *pt = GEOSGeom_createPointFromXY_r(*handle, px, py);
if (!pt) { GEOSGeom_destroy_r(*handle, line); FUZZ_BAIL(); }
