double dist = GEOSProject_r(*handle, line, pt);
if (dist < 0) {
    GEOSGeom_destroy_r(*handle, pt);
    GEOSGeom_destroy_r(*handle, line);
    FUZZ_BAIL();
}
// Cleanup temporaries
GEOSGeom_destroy_r(*handle, pt);
GEOSGeom_destroy_r(*handle, line);
// Validation: constructs minimal valid inputs and checks for exception sentinel.

// Build a 2-point LineString and interpolate a point at a finite distance.
GEOSCoordSequence *ls_seq = GEOSCoordSeq_createWithDimensions_r(*handle, 2u, 0, 0);
if (!ls_seq) { FUZZ_BAIL(); }
GEOSCoordSeq_setXY_r(*handle, ls_seq, 0u, *FUZZ_PARAM(double), *FUZZ_PARAM(double));
GEOSCoordSeq_setXY_r(*handle, ls_seq, 1u, *FUZZ_PARAM(double), *FUZZ_PARAM(double));
GEOSGeometry *line = GEOSGeom_createLineString_r(*handle, ls_seq);
if (!line) { FUZZ_BAIL(); }
// Use a bounded positive distance to avoid NaN/Inf.
double width = (double)((int)(*FUZZ_PARAM(unsigned int) % 1000u));
GEOSGeometry *out_pt = GEOSInterpolate_r(*handle, line, width);
if (!out_pt) { GEOSGeom_destroy_r(*handle, line); FUZZ_BAIL(); }
// Cleanup
GEOSGeom_destroy_r(*handle, out_pt);
GEOSGeom_destroy_r(*handle, line);
// Validation: ensures valid input line, finite distance, and frees output geometry.

// Create a LineString and a Point, then project normalized (expect [0,1] unless exception).
GEOSCoordSequence *ls_seq = GEOSCoordSeq_createWithDimensions_r(*handle, 2u, 0, 0);
if (!ls_seq) { FUZZ_BAIL(); }
GEOSCoordSeq_setXY_r(*handle, ls_seq, 0u, *FUZZ_PARAM(double), *FUZZ_PARAM(double));
GEOSCoordSeq_setXY_r(*handle, ls_seq, 1u, *FUZZ_PARAM(double), *FUZZ_PARAM(double));
GEOSGeometry *line = GEOSGeom_createLineString_r(*handle, ls_seq);
if (!line) { FUZZ_BAIL(); }
GEOSGeometry *pt = GEOSGeom_createPointFromXY_r(*handle, *FUZZ_PARAM(double), *FUZZ_PARAM(double));
if (!pt) { GEOSGeom_destroy_r(*handle, line); FUZZ_BAIL(); }
double t = GEOSProjectNormalized_r(*handle, line, pt);
if (t < 0) {
    GEOSGeom_destroy_r(*handle, pt);
    GEOSGeom_destroy_r(*handle, line);
    FUZZ_BAIL();
}
GEOSGeom_destroy_r(*handle, pt);
GEOSGeom_destroy_r(*handle, line);
// Validation: checks for exception sentinel and cleans up temporaries.

// Create a LineString and interpolate with a normalized fraction in [0,1].
GEOSCoordSequence *ls_seq = GEOSCoordSeq_createWithDimensions_r(*handle, 2u, 0, 0);
if (!ls_seq) { FUZZ_BAIL(); }
GEOSCoordSeq_setXY_r(*handle, ls_seq, 0u, *FUZZ_PARAM(double), *FUZZ_PARAM(double));
GEOSCoordSeq_setXY_r(*handle, ls_seq, 1u, *FUZZ_PARAM(double), *FUZZ_PARAM(double));
GEOSGeometry *line = GEOSGeom_createLineString_r(*handle, ls_seq);
if (!line) { FUZZ_BAIL(); }
// Normalized distance in [0,1]
double t = (double)(*FUZZ_PARAM(unsigned int) % 1001u) / 1000.0;
GEOSGeometry *out_pt = GEOSInterpolateNormalized_r(*handle, line, t);
